def binary_search(nums, target):
    low, high = 0, len(nums) - 1

    while low <= high:
        mid = low + (high - low) // 2
        if nums[mid] == target:
            return mid
        elif nums[mid] < target:
            low = mid + 1
        else:
            high = mid - 1

    return -1  # O(log n) time

def find_first(nums, target):
    low, high = 0, len(nums) - 1
    result = -1

    while low <= high:
        mid = low + (high - low) // 2
        if nums[mid] == target:
            result = mid
            high = mid - 1  # Search left
        elif nums[mid] < target:
            low = mid + 1
        else:
            high = mid - 1

    return result

def min_capacity(weights, D):
    low, high = max(weights), sum(weights)

    def can_ship(capacity):
        days = 1
        current = 0
        for w in weights:
            if current + w > capacity:
                days += 1
                current = w
            else:
                current += w
        return days <= D

    while low < high:
        mid = (low + high) // 2
        if can_ship(mid):
            high = mid
        else:
            low = mid + 1

    return low
